  "id": "ap-cpa-indeferimento-01",
  "law": "cpa",
  "topic": "Atos administrativos",
  "subtopic": "Dever de fundamentação",
  "conceptId": "cpa:indeferimento",
  "familyId": "cpa:indeferimento",
  "region": "Nacional",
