  "id": "ap-rgpd-apagamento-01",
  "law": "rgpd",
  "topic": "Proteção de dados",
  "subtopic": "Direito ao apagamento dos dados («direito a ser esquecido»)",
  "conceptId": "rgpd:retencao-legal",
  "familyId": "rgpd:retencao-legal",
  "region": "Nacional",
