  "id": "ap-rgpd-subcontratante-01",
  "law": "rgpd",
  "topic": "Proteção de dados",
  "subtopic": "Subcontratante",
  "conceptId": "rgpd:contrato-subcontratante",
  "familyId": "rgpd:contrato-subcontratante",
  "region": "Nacional",
